WITH cleaned AS (SELECT id, session_id, page, event_time, LENGTH(event_type) AS event_type_length, COALESCE(page, 'UNKNOWN') AS page_clean FROM web_events WHERE event_time > DATE '2023-07-30' AND session_id IN (36, 40)) SELECT CASE WHEN event_type_length >= 75 THEN 'LARGE' ELSE 'SMALL' END AS event_type_length_tier, MIN(event_time) AS started_at, COUNT_IF(page = '/home') AS home_events, SIZE(COLLECT_SET(page)) AS num_pages, AVG(event_type_length) AS avg_event_type_length, COUNT(CASE WHEN page = '/product' THEN 1 END) AS product_count FROM cleaned GROUP BY CASE WHEN event_type_length >= 75 THEN 'LARGE' ELSE 'SMALL' END
